local function fingerprint(name)
    if type(name) ~= "string" or not PawnCommon or not PawnCommon.Scales or not PawnCommon.Scales[name] then return end
    local ok, weights = --[[APR_DIAG]]
        APRPCall--[=[--[[/APR_DIAG]]pcall--[[APR_DIAG]]]=]--[[/APR_DIAG]](PawnGetAllStatValues, name)
    if not ok or type(weights) ~= "table" then return end
    local keys = {}
    for stat, value in pairs(weights) do
        if not ordinary(stat) or type(stat) ~= "string" or not finite(value) then return end
        keys[#keys + 1] = stat
    end
    table.sort(keys)
    local parts = {}
    for _, stat in ipairs(keys) do
        parts[#parts + 1] = #stat .. ":" .. stat .. "=" .. string.format("%.17g", weights[stat])
    end
    -- The public weight table excludes normalization and class/spec metadata.
    -- Read those fields without ever changing Pawn's SavedVariables.
    local scale = PawnCommon and PawnCommon.Scales and PawnCommon.Scales[name]
    for _, key in ipairs({ "NormalizationFactor", "ClassID", "SpecID" }) do
        local value = scale and scale[key]
        if value ~= nil and value ~= false then
            if value == true then value = 1 end
            if not finite(value) then return end
            parts[#parts + 1] = key .. "=" .. string.format("%.17g", value)
        end
    end
    return table.concat(parts, ";")
end--[[APR_DIAG]]
