function PawnRewards:UpdateSnapshot()
    local char = character()
    local scales = self:ReadScales()
    self.scales, self.ready = scales or {}, scales ~= nil
    if not char or not scales then
        self.pending = {}
        self:CancelPrompt()
        return
    end
    local seen = char.rewardPawnSeen
    local initial = not seen.initialized
    if initial then
        for name, scale in pairs(scales) do
            if scale.custom then seen.fingerprints[name] = scale.fingerprint end
        end
        seen.initialized = true
    end
    for name in pairs(seen.fingerprints) do
        if not scales[name] then seen.fingerprints[name] = nil end
    end
    for key, record in pairs(char.rewardPawnScales) do
        if
            type(record) ~= "table"
            or (record.mode ~= "apr" and (type(record.name) ~= "string" or type(record.fingerprint) ~= "string"))
        then
            char.rewardPawnScales[key] = nil
        end
    end
    local key = specializationKey()
    local selected = char.rewardPawnScales[key]
    local pending = {}
    for name, scale in pairs(scales) do
        local selectedChanged = selected and selected.name == name and selected.fingerprint ~= scale.fingerprint
        if selected and selected.name == name and not selectedChanged then
            if scale.custom then seen.fingerprints[name] = scale.fingerprint end
        elseif selectedChanged or (scale.custom and seen.fingerprints[name] ~= scale.fingerprint) then
            pending[name] = scale
        end
    end
    self.pending = pending
    local prompt = self.prompt
    if
        prompt
        and (
            prompt.key ~= key
            or prompt.profile ~= APR:GetSettingsProfile()
            or not pending[prompt.name]
            or pending[prompt.name].fingerprint ~= prompt.fingerprint
            or not self:IsAutomatic()
        )
    then
        self:CancelPrompt()
    end
end--[[APR_DIAG]]
