    APRTrace("APR-Core/integrations/Pawn.lua:385:PawnRewards:RefreshScoringContext#36", PawnRewards.RefreshScoringContext)--[[/APR_DIAG]]

function PawnRewards:RefreshSettings()
    self:CancelRefresh()
    self:InstallHooks()
    self:UpdateSnapshot()
    if not self:IsAutomatic() or not next(self.pending or {}) then
        self:CancelPrompt()
        self:UnregisterEvent("PLAYER_REGEN_ENABLED")
    end
    if self.ready then
        self:UnregisterEvent("ADDON_LOADED")
        self:UnregisterEvent("PLAYER_LOGIN")
    end
    self:TryPrompt()
    self:RefreshScoringContext()
    self:NotifyOptions()
end--[[APR_DIAG]]
