function PawnRewards:SetSelectedScale(name)
    self:UpdateSnapshot()
    local char = character()
    if not char then return false end
    local key = specializationKey()
    if name == "apr" or name == "auto" then
        char.rewardPawnScales[key] = name == "apr" and { mode = "apr" } or nil
    else
        if type(name) == "string" and name:sub(1, 5) == "pawn:" and self.scales[name:sub(6)] then
            name = name:sub(6)
        end
        local scale = self.scales[name]
        if not self.ready or not scale then return false end
        char.rewardPawnScales[key] = { name = name, fingerprint = scale.fingerprint }
        char.rewardPawnSeen.fingerprints[name] = scale.fingerprint
    end
    self:CancelPrompt()
    -- An explicit settings choice resolves the currently offered alternatives.
    for pendingName, scale in pairs(self.pending or {}) do
        char.rewardPawnSeen.fingerprints[pendingName] = scale.fingerprint
    end
    self.pending = {}
    self:RefreshScoringContext()
    self:NotifyOptions()
    return true
end--[[APR_DIAG]]
